[Thinking]
**Generating TCP server code**

I'm looking to create a simple TCP server code in C, likely following the POSIX standard. I want to keep the explanation minimal, just enough to understand the basic components of the code without overcomplicating things. It should include key elements like socket creation, binding, listening for connections, and accepting them. Let's focus on writing clean and straightforward code that effectively demonstrates the TCP server's structure and functionality!
[/Thinking]

Here is a minimal example of a TCP/IP server in C that:

- Listens on port 8080  
- Accepts one client connection  
- Receives a message  
- Sends a reply  
- Then exits  

```c
// tcp_server.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>         // close()
#include <arpa/inet.h>      // sockaddr_in, inet_ntoa()
#include <sys/socket.h>     // socket(), bind(), listen(), accept()

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE] = {0};
    const char *reply = "Hello from server\n";

    // 1. Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Optionally allow reuse of address/port
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // 2. Bind socket to IP/port
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;          // IPv4
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Listen on all interfaces
    server_addr.sin_port = htons(PORT);        // Port in network byte order

    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // 3. Listen
    if (listen(server_fd, 5) < 0) {
        perror("listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // 4. Accept a connection
    client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_addr_len);
    if (client_fd < 0) {
        perror("accept failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Connection accepted from %s:%d\n",
           inet_ntoa(client_addr.sin_addr),
           ntohs(client_addr.sin_port));

    // 5. Receive data
    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("read failed");
    } else {
        buffer[bytes_read] = '\0'; // null-terminate
        printf("Received: %s\n", buffer);
    }

    // 6. Send reply
    if (send(client_fd, reply, strlen(reply), 0) < 0) {
        perror("send failed");
    }

    // 7. Close sockets
    close(client_fd);
    close(server_fd);

    return 0;
}
```

### Compile and run

```bash
gcc tcp_server.c -o tcp_server
./tcp_server
```

Then from another terminal (on the same machine):

```bash
telnet 127.0.0.1 8080
# or
nc 127.0.0.1 8080
```

Type something and press Enter; the server will print what it received and send back “Hello from server”.  

If you want a version that handles multiple clients or runs in a loop, I can extend this.

